module tb_TopModule;
    logic clk;
    logic areset;
    logic j;
    logic k;
    logic out;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .j(j),
        .k(k),
        .out(out)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        j = 0;
        k = 0;

        #12;
        if (out !== 0) begin
            $display("SELFFAIL: Reset state output should be 0, got %b", out);
            $finish;
        end

        areset = 0;
        #10;
        // In OFF, j=0 should stay OFF
        j = 0; k = 0;
        #10;
        if (out !== 0) begin $display("SELFTEST FAIL: OFF with j=0"); $finish; end

        // In OFF, j=1 should go to ON
        j = 1; k = 0;
        #10;
        if (out !== 1) begin $display("SELFTEST FAIL: OFF with j=1 -> ON"); $finish; end

        // In ON, k=0 should stay ON
        j = 0; k = 0;
        #10;
        if (out !== 1) begin $display("SELFTEST FAIL: ON with k=0 -> ON"); $finish; end

        // In ON, k=1 should go to OFF
        j = 0; k = 1;
        #10;
        if (out !== 0) begin $display("SELFTEST FAIL: ON with k=1 -> OFF"); $finish; end

        // Asynchronous reset test
        j = 1; k = 0;
        #3;
        areset = 1;
        #2;
        if (out !== 0) begin $display("SELFTEST FAIL: async reset during cycle"); $finish; end
        areset = 0;
        #10;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
